// (recomputing contact_by) by calling
// CadenceUpdater.ApplyContactByOverride in the same tx;
// EnrichmentService uses this query for cadence-absent inferred fields
// and CadenceUpdater.ApplyContactByOverride when the input DTO carries
// an explicit cadence preference.
func (q *Queries) UpdateContact(ctx context.Context, arg UpdateContactParams) (*Contact, error) {
	row := q.db.QueryRow(ctx, UpdateContact,
		arg.ID,
		arg.FullName,
		arg.Cadence,
		arg.ProfilePhoto,
	)
	var i Contact
	err := row.Scan(
		&i.ID,
		&i.FullName,
		&i.Location,
		&i.Birthday,
		&i.HowMet,
		&i.Cadence,
		&i.LastContacted,
		&i.ProfilePhoto,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ContactBy,
		&i.LastInteractionAt,
		&i.LastOutreachAt,
		&i.LastResponseAt,
	)
	return &i, err
}

